const { parseAmount } = require('./money');

// order: { id, items: [{ sku, price: "12.50", qty }] }
function checkout(order) {
  const totalCents = order.items.reduce((sum, it) => sum + parseAmount(it.price) * it.qty, 0);
  return { orderId: order.id, totalCents };
}

module.exports = { checkout };
// Stand-in for the database layer; only its slow-query warnings show up in the log.
function slowQueryWarning(path) {
  return path.startsWith('/products') ? null : 'no query';
}

module.exports = { slowQueryWarning };
// Parses a user-entered amount such as "12.50" into integer cents.
// Throws Error('Invalid amount: <input>') for input that is not an amount.
function parseAmount(input) {
  const m = String(input).trim().match(/^(\d+)(?:\.(\d{1,2}))?$/);
  const whole = Number(m[1]);
  const frac = m[2] ? Number(m[2].padEnd(2, '0')) : 0;
  return whole * 100 + frac;
}

function formatCents(cents) {
  return (cents / 100).toFixed(2);
}

module.exports = { parseAmount, formatCents };
const { checkout } = require('./checkout');
const { slowQueryWarning } = require('./db');

function log(level, msg) {
  console.log(`${new Date().toISOString()} ${level} ${msg}`);
}

function handle(req) {
  if (req.method === 'POST' && req.path === '/checkout') {
    log('DEBUG', `checkout payload items=${JSON.stringify(req.body.items)}`);
    try {
      const result = checkout(req.body);
      log('INFO', `POST /checkout 200 order=${req.body.id} total=${result.totalCents}`);
      return { status: 200, body: result };
    } catch (e) {
      log('ERROR', `POST /checkout 500 order=${req.body.id} ${e.stack}`);
      return { status: 500, body: { error: 'INTERNAL' } };
    }
  }
  slowQueryWarning(req.path);
  return { status: 404, body: { error: 'NOT_FOUND' } };
}

module.exports = { handle };
